from pathlib import Path
import json, shutil

B=Path(__file__).resolve().parent
O=B.parent/'deliverables/通俗化重构版'
audit=[]
for key in ('product','system'):
    p=B/f'{key}.md'
    archive=B/'revisions/round0'
    archive.mkdir(parents=True,exist_ok=True)
    if not (archive/p.name).exists(): shutil.copy2(p,archive/p.name)

def para(key,prefix,new,ids):
    p=B/f'{key}.md'; parts=p.read_text().split('\n\n')
    hits=[i for i,s in enumerate(parts) if s.startswith(prefix)]
    assert len(hits)==1,(key,prefix,hits)
    i=hits[0]; old=parts[i]; parts[i]=new
    p.write_text('\n\n'.join(s for s in parts if s!=''))
    audit.append(dict(ids=ids,document=key,before=old,after=new,status='已修复'))

def sub(key,old,new,ids):
    p=B/f'{key}.md'; s=p.read_text(); assert s.count(old)==1,(key,old,s.count(old))
    p.write_text(s.replace(old,new)); audit.append(dict(ids=ids,document=key,before=old,after=new,status='已修复'))

para('product','教育部等九部门','教育部等九部门于2025年印发《关于加快推进教育数字化的意见》，提出推进优质资源共享和人工智能教育应用[ @digital ]。这些政策强调数字学习资源的建设与使用，也为课后学习工具提出了更具体的应用方向。\n\n与此同时，图像识别、语言模型和数字学习记录为工具提供了不同能力：读取试卷文字、回答学生提问，以及保存前后多次作答。怎样把这些能力用于日常订正，还需要从学生的实际困难出发。','P01')
para('product','本项目进一步关注','这些产品分别为解题理解或长期复习提供了成熟做法。错题帮关注的是学生在几个环节之间怎样继续学习：展示标准步骤之后，能否找到自己写错的地方；得到提示之后，能否保留这次求助；重新答题之后，结果能否用于下一次安排。','P02')
para('product','错题帮选择个人课后','错题帮选择个人课后错题学习作为实现范围，把原作答、订正时的求助和后续练习结果保存在一起。学生能够继续处理同一道错题；材料不足时，也可以返回原图核对、补写过程或修正记录。','P02')
para('product','AI讲解围绕当前题目','AI讲解围绕当前题目进行。对于需要完整讲解的题目，学生先回答理解问题，再用自己的话解释方法，随后完成相似题和改变情境的题目。答案较短或适合简化处理的题目，会缩短前面的讲解环节，围绕关键问题安排练习。学生还可以提出疑问，让解释针对当前卡住的地方。','P03')
para('product','当前复习采用明确','学生可选择“还不会”“有点困难”“基本掌握”或“很轻松”。系统结合本次正误安排日期。例如，同样选择“很轻松”，答对时安排15天后复习，答错时安排4天后复习；其他档位采用更短间隔。当前间隔由统一规则计算，后续可结合使用数据调整。复习界面保留结果与历史，便于回看同一道题的变化。','P04')
para('product','学习报告汇集','学习报告汇集已经保存的回答、任务和复习情况，学生可以返回相关题目。系统还根据已保存的答题结果和求助情况，计算一个安排练习时使用的参考值，称为“掌握估计”。它帮助系统选择下一项任务，不能直接理解为学生下一次考试会得到的分数。','P05')
para('product','同样答对一道题','同样答对一道题，可能是在完全独立时完成，也可能刚看过提示或完整答案。系统保存这些条件，再调整安排练习所使用的掌握估计。例如，提示后答对可以继续学习，但系统仍可能安排一次不看提示的回答，以取得新的判断依据。','P05')
para('product','在持久学习任务中','在可以中断后继续的本题学习任务中，系统读取上一次估计、本次答案是否正确，以及学生是否使用过帮助，再调整下一次安排练习所需的参考值。知识追踪研究讨论了怎样根据连续作答估计学习情况[ @knowledge_tracing ]；项目目前使用默认参数，后续还需要结合真实学生样本调整。','P06')
para('product','选择下一题时','选择下一题时，系统检查学科、剩余时间、近期是否做过以及是否已经到期。例如，只剩5分钟时，标记为预计20分钟的题会被排除。当前预计用时使用程序中的默认值，实际完成速度会因学生和题目而变化。符合条件的到期题优先，同一组内再比较薄弱程度和难度。','P07')
para('product','如果同一次提交','如果同一次提交因为网络问题发送了两遍，后端依据请求编号返回原有结果，避免重复登记。如果学生同时打开两个任务页面，并已在第一个页面完成订正，第二个页面再提交旧答案时，系统会提示刷新进度，避免把刚完成的步骤改回旧状态。','P08')
sub('product','系统已经采用仓颉业务服务与MySQL作为唯一业务主线，旧Python业务后端不再参与运行。','当前账号、题目和学习记录均由仓颉业务服务管理并保存到MySQL；Python只承担内部计算。','P09')
sub('product','模型请求统一经过ApiPoolProvider，使用逻辑模型Qwen','模型请求统一使用Qwen作为调用名称，由服务端管理请求和可用连接','P10')
sub('product','这种组织方式称为单协调器智能体','这个负责安排步骤、调用工具并接收结果的程序称为协调器，系统由同一个协调器管理当前任务','P10')
para('product','第三组案例来自','第三组案例在独立测试环境中运行。测试程序预先规定算法返回的题目和答案，再通过真实浏览器检查页面操作及保存结果。这组截图用于说明练习能否正确保存和恢复，不用于评价模型生成题目的质量。案例先保存练习“5x＋3＝－32”及回答“x＝－7”，再获取下一题“5x＋14＝44”。','P11')
para('product','截图中的估计数值','这组页面上的数值来自该练习入口的现行规则，不能直接与其他页面的估计值比较。本案例主要检查三件事：当前题目是否保存、回答是否关联到本题，以及重新进入后能否恢复同一次结果。','P12')
sub('product','### 5.4 持续复习案例','### 5.4 任务继续与复习','P13')
para('product','学生第二次打开','学生下一次打开应用时，首先需要找到未完成任务和应当复习的题目。首页提供继续入口，易错地图帮助从反复出现的问题找到原题，复习页面则保存这次重新回答的结果。图7展示已有任务的首页；首次使用时，则根据本人偏好提供录题和知识学习起点。','P13')
para('product','图8中的节点','图8中的标签与原题详情相连，学生可以回看当时的题目、原作答和诊断。查看这些材料之后，再决定需要补充条件、订正步骤，还是进行下一次练习。','P13')
para('product','第四组复习截图','图9展示一次复习操作：学生先提交“3x＝15，x＝5”，系统保存判定，再请学生评价回忆难度。这两张截图来自同一固定测试样本。','P13')
para('product','项目按前端组件','项目按前端组件、算法、仓颉业务、接口数据库和浏览器分别验证。前端单元测试检查组件和页面状态，算法测试检查计算规则和返回结构，仓颉测试检查业务条件，接口测试检查实际保存；浏览器测试和跨视口专项再检查学生操作及页面呈现。','P15')
sub('product','| 同题跨视口检查 |','| 数学与化学局部修复 | 3个文件、56项通过 | 公式文本、化学分组和内容呈现 |\n| 同题跨视口检查 |','P14')
para('product','上述批次的实施记录','表2分别保留完整回归和后续专项检查。当前文档按源码0092d19核对；全部记录保留2026年10月22日的测试日期。专项只说明相应修改已经检查，不与完整回归合并计数。各批结果均有对应日志。','P14')
para('product','对学生而言，系统减少','学生在模拟考试中答错后，可以把当时的题目、配图和答案直接加入错题本；日后订正或复习时，仍能看到这次回答。需要手动重新整理的材料，主要是原题尚不完整或识别需要修正的部分。','P16')

sub('system','计算成功只能说明产生了一个结果，能否保存还取决于题目和任务是否保持有效。','算法返回结果后，仓颉还要检查题干和作答是否已被修改、学生是否仍处于同一步，以及任务是否已取消。只有这些条件仍与计算开始时相符，结果才会写入当前任务。','S01')
para('system','本报告按2026年','本报告按源码版本0092d19核对，引用2026年10月22日完整回归及随后专项检查的原始记录。下文分别标明测试批次、检查对象和结果，不将文档编写日期当作测试日期[ @project ]。','S02')
para('system','耗时本题学习','本题学习中的分析可能需要等待模型返回，因此系统把这类计算放入后台任务。页面先得到已受理的任务编号，再查询处理进度；学生不必一直保持同一页面打开。需要回答时，任务等待新输入；学生提交后，仓颉登记请求，工作器再继续处理。','S03')
sub('system','页面使用最后形成的公开视图，不能把工具还未检查的模型建议直接显示为业务完成。','仓颉最后整理出学生当前可以看到的题目、反馈和操作按钮，供页面显示，这份返回页面的数据称为公开视图。例如，模型建议进入下一题，但本次答案仍待核对时，页面继续提示核对，不会显示本题已经完成。','S04')
sub('system','接口变化时需要同步核对消费者。','接口字段发生变化时，前端和调用该接口的服务也要同步检查，避免一方已经改名，另一方仍读取旧字段。','S05')
para('system','当前多项式核验','这套多项式检查目前处理只有一个未知数、次数为1至4次，而且至少有一个、数量有限的实数解的方程。程序还需要能够解析学生写出的方程或解值。例如，2x＋3＝11和x²＝4可以进入检查；文字证明、复杂几何及无法解析的写法需要其他处理。不等式另有专门模块。SymPy的集合式求解用于比较解和边界[ @sympy ]。','S06')
sub('system','采用默认先验0.35','先把掌握估计设为0.35，这个起始值称为先验','S07')
sub('system','权重作用于两类似然','L₁与L₀分别表示在“已经掌握”和“尚未掌握”两种假设下，出现本次回答的可能程度，统计上称为似然。这些是程序的默认参数，不是学生实验测得的比例。权重作用于两类似然','S07')
sub('system','正确回答再加入学习转移项','答对后，程序还按默认参数增加一小部分估计值，表示本次练习可能带来的学习，代码称其为学习转移项','S07')
para('system','计算前先筛选回答','计算前先检查本次回答。题目已经修改、判题仍待核对、同一次提交重复到达，或只改了一个局部步骤时，系统不把它计为一次新的整题作答。看过完整答案后的答对保留为辅助学习；只使用提示的回答仍可参与计算，但影响较小。','S08')
para('system','仓颉采用更新前','准备保存新估计时，仓颉再次检查学生确实提交了当前阶段的回答、判题已确认正误、所用题目仍未改变，而且这次请求尚未登记。Python也检查最近事件是否重复，跨请求去重由数据库和事务完成。条件对照还要检查学生是否已见过同一道对照题，避免重复出现的题被当作全新的独立回答。','S08')
para('system','系统还计算不确定性','系统还计算不确定性和遗忘风险。估计接近0.5时，现有记录还难以区分“已经掌握”与“尚未掌握”，系统记为较高的不确定性。公式使用二元熵H(p)表示这一程度；p越接近0或1，不确定性越低。遗忘风险结合估计和距上次有效回答的天数d，默认时间参数τ＝30天。','S09')
para('system','学习规划接收','学习规划接收当前阶段、材料是否充分、基础知识、近期错误、学科、剩余时间和候选题。程序给出当前最建议学生进行的一项操作，最多再保留两项可选操作，例如先订正本题、回顾某张知识卡或复习一道到期题。选择范围限于当前已经提供且允许使用的内容。','S10')
para('system','输入最多组织','每次计算最多接收200道待选题、400项“知识点及其掌握估计”记录、100个知识点和6张知识卡的标识。限制数量可以控制本次计算量。没有候选题时，有相关知识卡则可回顾，否则结束。最终返回的题目必须来自本批已提供内容，仓颉再次核对标识，模型不能临时编造一道数据库题目供页面跳转。','S10')
sub('system','G采用归一化的信息增益','G使用信息增益，并把超过1的结果按1计入。信息增益估计回答本题后能减少多少判断上的不确定性，其计算在第4.4节给出','S11')
para('system','检索查询包含','检索查询包含题干、选项、学科、年级和知识目标。检索同时采用两种找题方式：一种把题目转为数值表示，寻找含义接近的内容，称为稠密检索；另一种保留词项联系，补充关键用词的匹配，称为稀疏检索。系统合并两路结果，再用重排模型比较候选与当前目标，调整先后顺序。默认使用BGE-M3及BGE-reranker-v2-m3，融合采用倒数排名法[ @qdrant ][ @bge ]。','S12')
para('system','排序之后还要','排序之后还要判断是否检验相同知识和方法。两道题都出现“方程”一词，并不意味着都在练习解一元一次方程。直接给出方程的题，可以检查它是否仍要求相同运算；文字题还需核对未知量及其数量关系；其他目标需要原题及候选中的实际引文支持。不能确认练习目标相同的题不进入本轮练习。','S13')
para('system','题库选题使用贝叶斯','题库选题使用贝叶斯知识追踪式计算，即根据前一次估计及新回答调整知识状态。设p为已有估计，s为已经掌握时仍答错的失误项，g为尚未掌握时答对的猜测项。一道题涉及k个知识点时，程序把本次回答对每个知识点的影响按1/k分配。对其中一个知识点，答对和答错后的估计分别为：','S14')
sub('system','p′_正确 = p(1−s) / [p(1−s)+(1−p)g]','p′_正确 = p(1−s)^(1/k) / [p(1−s)^(1/k)+(1−p)g^(1/k)]','S14')
sub('system','p′_错误 = ps / [ps+(1−p)(1−g)]','p′_错误 = ps^(1/k) / [ps^(1/k)+(1−p)(1−g)^(1/k)]','S14')
para('system','当前默认s＝','当前默认s＝0.1，非选择题g＝0.05，选择题按选项数确定。随后计算p_new＝p′＋(1－p′)×0.08/k；k＝1时，每个知识点承受完整一次回答的影响。此路径在答错后也加入该项，与第4.1节本题任务只在答对后增加学习项的规则不同。\n\n例如，初始p＝0.35，一道非选择题关联两个知识点，学生答对时，对每个知识点使用权重0.5。代入后得到p′约0.695540；再计入0.08/2的学习项，结果约0.707718。如果漏掉似然的0.5次方，便会把同一次回答的影响完整计入两个知识点，得到不同数值。此算例用于复核程序计算，不表示真实学生能力达到70.8%。','S14')
para('system','信息增益衡量','信息增益衡量回答这道题后预计能减少多少不确定性。先计算答对概率q＝p(1－s)＋(1－p)g，再比较回答前的熵与答对、答错后熵的加权平均。此处评估单个知识点可能获得的信息，计算两种后验时使用权重1；保存一次多知识点作答时才使用前述1/k权重。负的浮点计算结果按0处理。','S14')
sub('system','IG = H(p) − qH(p′_正确) − (1−q)H(p′_错误)','IG = max(0，H(p) − qH(p′_正确) − (1−q)H(p′_错误))','S14')
sub('system','score = IG + 0.30W − 0.30E_q − 0.08R_k','score = G + 0.30W − 0.30E_q − 0.08R_k','S14')
para('system','W表示薄弱程度','G为该题各知识点信息增益的平均值，W＝1－各知识点掌握估计的平均值；E_q是该题已提交次数；R_k是本批已选题对该题知识标签的平均重复次数。批量选择逐题进行，选入一题后更新批内重复信息。这套算法用于题库自适应练习。模拟考试另按会话规则准备题目，不会在答题过程中按上述分数更换试题，代码分别以practice和exam表示两种模式。','S14 S15')
para('system','初次进入复习计划','初次进入复习计划与到期后的再次安排有所区别。AI讲解结束后，若迁移练习中的回答还不稳定，先安排1天后复习；其余情况下，使用过帮助的安排3天后复习，没有相应帮助记录的安排15天后复习。表4用于学生进入复习页面、重新答题并完成自评后的下一次安排。Anki资料提供持续复习产品的参考[ @anki ]，本项目使用这里列出的固定间隔规则。','S16')
sub('system','它们共享题目和学习记录，各自保留阶段及结果合同。','这些入口可以使用同一道原题和已有学习记录，但分别保存当前阶段，并按各自规则判定是否完成。因此，AI讲解完成不会自动替代本题订正或一次独立练习。','S17')
para('system','持久学习任务使用LangGraph','一次本题任务调用依次进行错因诊断、处理学生动作、更新掌握估计和选择下一步；需要补充材料时，转入核对分支并返回页面。代码中的节点名分别为eced、student_action、aemt、arpp和confirm，使用LangGraph的StateGraph连接。','S18')
sub('system','材料不足可以结束本次计算并返回“需要核对”，执行结束与学习任务完成分别表示。','材料不足时，Python结束本次计算，页面请学生补充信息；学习任务仍未完成。学生补充后，仓颉再发起下一次调用。只有当前学习步骤都按规则处理完，任务才进入完成状态。','S19')
para('system','工具调用采用允许列表','系统只允许执行预先登记的工具，不能根据模型临时写出的名称调用任意程序。工具包括步骤检查、答案判定、知识检索、步骤对齐、条件对照、手写识别、题图检查和交互图解。','S20')
sub('system','| 步骤检查 |','| 步骤检查 check_step |','S20')
sub('system','| 回答判定 |','| 回答判定 grade_answer |','S20')
sub('system','| 知识检索 |','| 知识检索 knowledge_search |','S20')
sub('system','| 条件对照 |','| 条件对照 compare_variant |','S20')
sub('system','| 手写识别 |','| 手写识别 recognize_handwriting |','S20')
sub('system','| 图解生成 |','| 图解生成 visualization |','S20')
sub('system','工具返回会改变后续处理。','步骤对齐step_alignment比较原步骤与参考步骤的关系，题图检查inspect_figure补充图片中可以确认的条件。二者保留各自引用，不替代学生的原作答。\n\n工具返回会改变后续处理。','S20')
para('system','理解检查使用题目','理解检查使用题目内容准备检查题，保存学生选择及反馈。复述阶段要求学生用自己的话解释做法。当前程序检查回答长度、是否出现“因为、所以、先、再”等表达，以及是否提到当前概念；缺少这些线索时要求补充。连续补充仍未通过时，系统可以记录为接受帮助后继续练习，因此进入下一阶段不一定表示复述已经通过。这里使用基础文字规则，没有把它当作对整段证明的完整语义评分。','S21')
para('system','学生追问使用','学生追问时，程序先判断他是在请求提示、提出新疑问，还是需要补充理由，再选择相应解释或允许的工具。代码中的tutor_graph组织这些分支，agent_compute准备本轮工具计划。追问结束后返回原教学阶段，学生仍需要完成该阶段的回答，追问本身不增加掌握估计。','S22')
para('system','执行状态与学习阶段','系统同时记录“程序现在在做什么”和“学生现在学到哪一步”。例如，程序可能已经算完并等待学生，而学生正在完成整题重做；也可能同样等待学生，但这次需要回答改变条件后的题目。前者称为执行状态，后者称为学习阶段。学习阶段包括局部订正repair、整题重做independent、条件对照contrast和结束done。','S23')
para('system','稳定的身份','用户编号、题目标识、保存时间、状态和版本分别保存在独立数据库字段中，便于查询和比较。一次考试使用的完整题目副本、任务恢复进度和判题细节则按固定JSON结构保存。数据库外键维护记录之间的关联，业务查询仍需检查这些记录是否属于当前学生。','S24')
para('system','学习任务的数据约束','系统为不同操作设置各自的唯一编号。同一学生使用同一请求编号创建任务时，不会创建两个任务；同一任务重复收到相同动作编号时，不会登记两次回答。工具执行记录还区分该请求内的步骤顺序，对照题则比较学生和题目内容，防止重复出现的题被当作新的独立练习。题目标识只能说明处理的是哪道题，不能单独完成这些区分。','S25')
para('system','同一道题可能多次编辑','系统把本次计算所用的题干、原作答、参考分析和诊断内容组合成一份比较依据，称为来源指纹。结果返回时，程序再次读取这些内容；如果已经改变，就不能把旧结果保存为当前分析。题目标识说明“哪一道题”，版本和内容比较则说明“哪一次内容”。','S26')
sub('system','相关任务会被检查并标为来源不再当前','相关任务会被检查，并标记为不再适用于当前材料','S26')
para('system','本题工作器的主要算法调用','本题工作器先完成主要算法计算，再开启结果保存事务，重新核对题目和任务后写入。这种把主要计算放在结果事务之外的安排，只适用于本题后台任务。当前复习判题、组卷导出和部分掌握保存过程，会在数据库事务尚未结束时等待算法返回。调用较慢时，相关数据可能被锁定更久，因此后续需要分别检查等待时间与超时影响。','S27')
para('system','系统需要在后续任务中','每次安排新任务时，仓颉从已保存记录中选取与当前题目有关的历史，例如近期答错的地方、已经确认的回答、复习结果和学生自己的总结。这份供本次计算使用的历史摘要称为学习记忆。各条摘要保留原记录、时间和版本，系统可以说明建议究竟参考了哪一次作答。','S28')
sub('system','当前共有36个注册页面，页面数量用于覆盖检查，功能是否完成仍以具体操作及结果为准。','当前路由配置登记了36个页面，包括学生主入口、题目详情和具体学习页面。页面数量用于检查是否有遗漏，功能完成仍以操作后得到的结果为准。','S29')
sub('system','本文说明产品导出能力，本次文档交付本身仅生成Word。','','S30')
para('system','Python内部服务验证','Python内部服务验证服务认证和请求结构，按操作分发计算。识别返回候选题目，诊断返回原因及引用，判题返回答案是否正确，以及这一判断是否已经确认、仍待核对或未能完成。任务计算返回页面数据及进度，导出计算返回文件产物。仓颉继续检查题目是否修改、回答是否属于当前学生和当前步骤，再决定是否保存并推进任务。','S31')
sub('system','| 专项页面检查 |','| 数学与化学局部修复 | 3个文件、56项通过 | cuoti-chem-layout-final-targeted.log；公式文本、分组与内容显示 |\n| 专项页面检查 |','S32')
para('system','后续化学显示专项','后续化学显示专项使用同一铅蓄电池原题，检查题干、选项、解析、下标、电荷和宽度。375与1280像素代表不同视口，不代表两个学生样本。随后针对数学与化学分组的局部回归在3个测试文件中通过56项，保留为独立专项。','S32')
para('system','测试批次的命令','表12分别列出完整回归和后续专项。专项结果只说明对应修改已经检查，不能与完整回归数量相加。每批记录保留原时间、命令和日志，便于核对。','S32')
sub('system','正向样例包含正确前缀后出现不等价步骤；反向样例包含正确短解、合法分支、没有步骤但有答案、步骤标识伪造和原文不匹配。','需要发现错误的样例先给出正确步骤，再加入一个改变原题解的步骤；需要避免误报的样例则使用正确短解或合法分支。另外检查只有答案、步骤标识伪造和原文不匹配时的处理。','S33')
sub('system','当前工作器采用同源结果','持有当前执行资格的工作器保存仍对应原题的结果','S33')
for prefix in ('模型质量评测应建立','学习效果评价需要记录','移动验收按设备'):
    p=B/'system.md'; chunks=p.read_text().split('\n\n'); q=next(s for s in chunks if s.startswith(prefix))
